contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 tokenId) public payable {
        require(true);
        uint256 count = c.uniqueTokensOutstanding(); if (__ESBMC_reverted()) return;
        require(tokenId >= count);

        bool reverted;
        c.safeTransferFrom(address(this), address(this), tokenId, 1, bytes("")); if (__ESBMC_reverted()) return;
        reverted = false;

        assert(!(tokenId >= c.uniqueTokensOutstanding()) || reverted);
    }
    receive() external payable {}
}

