    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    GameItems c;

    function setUp() public {
        c = new GameItems(address(this), address(this));
    }

    function _run(uint256 tokenId) internal {
        vm.assume(true);
        uint256 count;
        try c.uniqueTokensOutstanding() returns (uint256 __r) { count = __r; } catch { return; }
        vm.assume(tokenId >= count);
        bool reverted;
        try c.safeTransferFrom(address(this), address(this), tokenId, 1, bytes("")) {} catch { return; }
        reverted = false;
        assertTrue(!(tokenId >= c.uniqueTokensOutstanding()) || reverted);
    }

    function testFuzz_run(uint256 tokenId) public {
        _run(tokenId);
